using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
public partial class Studio {
 TextBlock montageSelectionLabel;CheckBox montageTrackMute,montageTrackHide,montageTrackLock;
 void BuildMontageInspector(){
  montageInspector.Children.Add(MT("ПРОЕКТ",13));montageAspect=MCombo(new[]{"9:16 • вертикально","1:1 • квадрат","16:9 • горизонтально"},0,delegate{montage.Aspect=montageAspect.SelectedIndex;MontageChanged();});montageInspector.Children.Add(montageAspect);
  var output=new StackPanel{Orientation=Orientation.Horizontal};montageQuality=MCombo(new[]{"1080","720"},0,delegate{montage.Resolution=montageQuality.SelectedIndex;MontageChanged();});montageQuality.Width=110;montageFps=MCombo(new[]{"30 fps","60 fps"},0,delegate{montage.Fps=montageFps.SelectedIndex==1?60:30;MontageChanged();});montageFps.Width=120;output.Children.Add(montageQuality);output.Children.Add(montageFps);montageInspector.Children.Add(output);
  montageSelectionLabel=MT("Выберите клип или дорожку",14);montageInspector.Children.Add(montageSelectionLabel);
  var trackButtons=new WrapPanel();trackButtons.Children.Add(MB("Дорожка ↑",delegate{MoveMontageTrack(-1);}));trackButtons.Children.Add(MB("Дорожка ↓",delegate{MoveMontageTrack(1);}));trackButtons.Children.Add(MB("Удалить дорожку",RemoveMontageTrack));montageInspector.Children.Add(trackButtons);
  montageTrackMute=MCheck("Заглушить звук дорожки",delegate(bool v){var t=CurrentMontageTrack();if(t!=null)t.Muted=v;});montageTrackHide=MCheck("Скрыть дорожку",delegate(bool v){var t=CurrentMontageTrack();if(t!=null)t.Hidden=v;});montageTrackLock=MCheck("Заблокировать дорожку",delegate(bool v){var t=CurrentMontageTrack();if(t!=null)t.Locked=v;});
  montageInspector.Children.Add(MT("ВРЕМЯ КЛИПА • секунды исходника / проекта"));montageStart=MField("Начало на шкале");montageIn=MField("Вход в исходник");montageLength=MField("Длина на шкале");montageInspector.Children.Add(MB("Применить время",ApplyMontageTime));
  var fitting=new WrapPanel();fitting.Children.Add(MB("Вписать",delegate{FitMontage(false);}));fitting.Children.Add(MB("Заполнить",delegate{FitMontage(true);}));montageInspector.Children.Add(fitting);
  MSlider("Speed","Скорость",.5,2,1);MSlider("Volume","Громкость",0,200,100);MSlider("Scale","Масштаб, % ширины кадра",10,500,100);MSlider("X","Положение X, %",0,100,50);MSlider("Y","Положение Y, %",0,100,50);MSlider("Rotation","Поворот, °",-180,180,0);MSlider("Opacity","Прозрачность, %",0,100,100);MSlider("Fade","Появление / исчезновение, с",0,2,0);
  montageInspector.Children.Add(MT("МАСКА"));montageMask=MCombo(new[]{"Без маски","Круг","Овал","Скруглённый прямоугольник"},0,delegate{if(CanEditMontage()){SelectedMontage().Mask=montageMask.SelectedIndex;MontageChanged();}});montageInspector.Children.Add(montageMask);
  montageInspector.Children.Add(MT("ФИЛЬТР"));montageFilter=MCombo(new[]{"Оригинал","Кино • контраст","Тёплый","Холодный","Чёрно-белый","Яркий"},0,delegate{if(CanEditMontage()){SelectedMontage().Filter=montageFilter.SelectedIndex;MontageChanged();}});montageInspector.Children.Add(montageFilter);
  montageInspector.Children.Add(MT("ТЕКСТ"));montageText=new TextBox{AcceptsReturn=true,Height=75,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,0,6)};montageText.TextChanged+=delegate{if(!montageUpdating&&CanEditMontage()){SelectedMontage().Text=montageText.Text;MontageChanged();}};montageInspector.Children.Add(montageText);
  montageStyle=MCombo(new[]{"Белый • обводка","Жёлтый • игровой","Фиолетовая плашка","Тёмная плашка","Голубой • неон","Минимализм"},0,delegate{if(CanEditMontage()){SelectedMontage().Style=montageStyle.SelectedIndex;MontageChanged();}});montageInspector.Children.Add(montageStyle);MSlider("Font","Размер текста, px при 1080",16,160,64);
 }
 CheckBox MCheck(string text,Action<bool> changed){var b=new CheckBox{Content=text,Margin=new Thickness(0,5,0,5)};b.Checked+=delegate{if(!montageUpdating){changed(true);MontageChanged();FillMontageInspector();}};b.Unchecked+=delegate{if(!montageUpdating){changed(false);MontageChanged();FillMontageInspector();}};montageInspector.Children.Add(b);return b;}
 TextBox MField(string label){montageInspector.Children.Add(MT(label));var t=new TextBox{Margin=new Thickness(0,0,0,5)};montageInspector.Children.Add(t);return t;}
 void MSlider(string key,string caption,double lo,double hi,double initial){var label=MT(caption);montageInspector.Children.Add(label);var s=new Slider{Minimum=lo,Maximum=hi,Value=initial,Margin=new Thickness(0,0,0,8),IsEnabled=false};montageSliders[key]=s;s.ValueChanged+=delegate{label.Text=caption+" • "+s.Value.ToString("0.##");if(montageUpdating||!CanEditMontage())return;var c=SelectedMontage();if(key=="Speed"){double amount=c.Length*c.Speed;if(amount/s.Value<.099999||c.Start+amount/s.Value>86400){montageUpdating=true;s.Value=c.Speed;montageUpdating=false;Status("При этой скорости клип слишком короткий или проект превышает 24 часа.");return;}c.Speed=s.Value;c.Length=amount/c.Speed;montageLength.Text=N(c.Length);}else if(key=="Volume")c.Volume=s.Value;else if(key=="Scale")c.Scale=s.Value;else if(key=="X")c.X=s.Value;else if(key=="Y")c.Y=s.Value;else if(key=="Rotation")c.Rotation=s.Value;else if(key=="Opacity")c.Opacity=s.Value;else if(key=="Fade")c.Fade=s.Value;else if(key=="Font")c.Font=s.Value;MontageChanged();};montageInspector.Children.Add(s);}
 MontageTrack CurrentMontageTrack(){return montage.Tracks.FirstOrDefault(t=>t.Id==montageTrackSelection);}
 void MoveMontageTrack(int delta){var t=CurrentMontageTrack();if(t==null||t.Locked)return;int i=montage.Tracks.IndexOf(t),j=i+delta;if(j<0||j>=montage.Tracks.Count)return;montage.Tracks.RemoveAt(i);montage.Tracks.Insert(j,t);MontageChanged();FlushMontageHistory();}
 void RemoveMontageTrack(){var t=CurrentMontageTrack();if(t==null||t.Locked)return;montage.Items.RemoveAll(c=>c.Track==t.Id);montage.Tracks.Remove(t);SelectMontage(null);montageTrackSelection=null;MontageChanged();FlushMontageHistory();}
 void FillMontageInspector(){if(montageInspector==null)return;montageUpdating=true;try{montageAspect.SelectedIndex=montage.Aspect;montageQuality.SelectedIndex=montage.Resolution;montageFps.SelectedIndex=montage.Fps==60?1:0;var c=SelectedMontage();var t=c==null?CurrentMontageTrack():TrackOf(c);montageSelectionLabel.Text=t==null?"Выберите клип или дорожку":t.Name+(c==null?"":" • клип");montageTrackHide.IsChecked=t!=null&&t.Hidden;montageTrackLock.IsChecked=t!=null&&t.Locked;montageTrackMute.IsChecked=t!=null&&t.Muted;
   bool edit=c!=null&&t!=null&&!t.Locked;foreach(var s in montageSliders.Values)s.IsEnabled=edit;montageText.IsEnabled=edit&&t.Kind=="text";montageStyle.IsEnabled=montageText.IsEnabled;montageMask.IsEnabled=edit&&t.Kind=="video";montageFilter.IsEnabled=montageMask.IsEnabled;montageStart.IsEnabled=montageIn.IsEnabled=montageLength.IsEnabled=edit;
   if(c==null)return;montageStart.Text=N(c.Start);montageIn.Text=N(c.In);montageLength.Text=N(c.Length);montageText.Text=c.Text??"";montageMask.SelectedIndex=c.Mask;montageStyle.SelectedIndex=c.Style;montageFilter.SelectedIndex=c.Filter;
   montageSliders["Speed"].Value=c.Speed;montageSliders["Volume"].Value=c.Volume;montageSliders["Scale"].Value=c.Scale;montageSliders["X"].Value=c.X;montageSliders["Y"].Value=c.Y;montageSliders["Rotation"].Value=c.Rotation;montageSliders["Opacity"].Value=c.Opacity;montageSliders["Fade"].Value=c.Fade;montageSliders["Font"].Value=c.Font;
  }finally{montageUpdating=false;}}
 void ApplyMontageTime(){if(!CanEditMontage())return;var c=SelectedMontage();double start=ParseTime(montageStart.Text),input=ParseTime(montageIn.Text),len=ParseTime(montageLength.Text);var a=AssetOf(c);if(start<0||input<0||len<.1||start+len>86400)throw new Exception("Начало ≥ 0, длина ≥ 0,1 с; проект не длиннее 24 часов.");if(a!=null&&a.Kind!="image"&&input+len*c.Speed>a.Duration+.002)throw new Exception("Границы клипа выходят за длительность исходника.");c.Start=start;c.In=input;c.Length=len;MontageChanged();FlushMontageHistory();}
 void FitMontage(bool fill){if(!CanEditMontage()||TrackOf(SelectedMontage()).Kind!="video")return;var c=SelectedMontage();var a=AssetOf(c);if(a==null||a.Width<=0||a.Height<=0)return;int w,h;Dimensions(new EditSettings{Aspect=montage.Aspect,Resolution=montage.Resolution},false,out w,out h);double ratio=c.Mask==1?1:a.Width/(double)a.Height;double scale=h/(double)w*ratio*100;c.Scale=Math.Max(10,Math.Min(500,fill?Math.Max(100,scale):Math.Min(100,scale)));c.X=c.Y=50;FillMontageInspector();MontageChanged();}

}
